// === Tab: mySketch ===
let fbo
let font
let particles
let particleShader

async function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)
	font = await loadFont('https://fonts.gstatic.com/s/ubuntu/v21/4iCv6KVjbNBYlgoCxCvTt2aMH4V_gg.ttf')
	fbo = createFramebuffer({ width: 150, height: 75, density: 1 })

	fbo.draw(() => {
		background(0)
		fill(255)
		textFont(font)
		textAlign(CENTER, CENTER)
		textSize(30)
		text('P5UR1BUS', 0, 0)
	})
	fbo.loadPixels()

	particles = buildGeometry(() => {
		noFill()
		translate(-fbo.width/2, -fbo.height/2)
		beginShape(LINES)
		// Foreground particles
		for (let x = 0; x < fbo.width; x++) {
			for (let y = 0; y < fbo.height; y++) {
				if (fbo.pixels[(y * fbo.width + x) * 4] > 0) {
					vertex(x, y)
					vertex(x + 0.001, y)
				}
			}
		}

		// Background particles
		const origin = createVector(fbo.width/2 - 70, fbo.height/2)
		for (let i = 0; i < 4000; i++) {
			let x = floor(random(-1, 2) * fbo.width)
			let y = floor(random(-1, 2) * fbo.height)
			const r = Math.hypot(x - origin.x, y - origin.y)
			const theta = Math.atan2(y - origin.y, x - origin.x)
			const snappedR = floor(r / 20) * 20
			const newR = snappedR + randomGaussian(0, 4)
			x = floor((origin.x + newR * cos(theta))*5)/5
			y = floor((origin.y + newR * sin(theta))*5)/5
			vertex(x, y)
			vertex(x + 0.001, y)
		}
		endShape()
	})

	particleShader = baseStrokeShader().modify(() => {
		const t = uniformFloat(() => millis())
		getObjectInputs((inputs) => {
			const pos = floor(inputs.position.xy * 5) / 5
			const seed = pos * Math.PI

			const orig = [-70, 0]
			const origR = length(orig - pos)

			const startTime = origR / 50 * 1000
			const endTime = startTime + 4000
			const progress = smoothstep(startTime, endTime, t)

			inputs.weight *= smoothstep(
				startTime - 1000,
				endTime + 1000,
				t
			) * mix(0.7, 1, 1-noise(seed))

			inputs.position.xy = mix(
				pos + [
					200 * (noise(seed.x, seed.y, 1000) - 0.3),
					100 * (noise(seed.x, seed.y, 1200) - 0.3),
				],
				pos,
				progress,
			)

			const diff = inputs.position.xy - orig
			const dir = normalize(diff)
			var r = length(diff)
			var theta = atan(diff.y, diff.x)
			let finalRippleScale = 0.2
			if (abs(pos.x) > 150/2) {
				finalRippleScale = 1
			}
			if (abs(pos.y) > 15) {
				finalRippleScale = 1
			}
			const rippleScale = mix(2, finalRippleScale, progress)
			const off = rippleScale * sin(r - t * 0.01)
			const noiseScale = mix(2, 0.1, progress)

			inputs.position.xy += off * dir
			inputs.position.xy += noiseScale * [
				noise(seed.x, seed.y, t * 0.001),
				noise(seed.x, seed.y, t * 0.001 + 100),
			]
			return inputs
		})
	})
}

function draw() {
	background(0)
	noFill()
	stroke(255)
	strokeWeight(5)
	push()
	scale(min(width/180, height/115))
	strokeShader(particleShader)
	model(particles)
	pop()
}

